    async def list(
        self,
        *,
        status: Literal["edge_only", "pending", "storing", "stored", "removed"] | None = None,
        type: Literal["image", "video", "audio"] | None = None,
        content_type: str | None = None,
        duration_min: float | None = None,
        duration_max: float | None = None,
        created_at_from: str | None = None,
        created_at_to: str | None = None,
        cached_at_from: str | None = None,
        cached_at_to: str | None = None,
        limit: int | None = None,
        cursor: str | None = None,
        sort: Literal["createdAt_desc", "createdAt_asc", "cachedAt_desc", "cachedAt_asc", "duration_desc", "duration_asc"] | None = None,
        linked_account_id: str | None = None,
    ) -> dict[str, Any]:
        """Query Vault+ media

        Query cached media for the Connection. Items are grouped by raw OnlyFans media id with variants keyed by label.

        Args:
            linked_account_id: Linked account to act on (`x-linked-account-id`). Defaults to the client's.

        Returns:
            Parsed JSON, shaped like `models.VaultPlusMediaList`.

        Example:
            await client.vault_plus.media.list()
        """
        return await self._client.request(
            "GET",
            "/v3/vault-plus/media",
            query={"status": status, "type": type, "contentType": content_type, "durationMin": duration_min, "durationMax": duration_max, "createdAtFrom": created_at_from, "createdAtTo": created_at_to, "cachedAtFrom": cached_at_from, "cachedAtTo": cached_at_to, "limit": limit, "cursor": cursor, "sort": sort},
            linked_account=True,
            linked_account_id=linked_account_id,
            operation="vaultPlus.media.list",
            scope=None,
        )

    def iterate(
        self,
        *,
        status: Literal["edge_only", "pending", "storing", "stored", "removed"] | None = None,
        type: Literal["image", "video", "audio"] | None = None,
        content_type: str | None = None,
        duration_min: float | None = None,
        duration_max: float | None = None,
        created_at_from: str | None = None,
        created_at_to: str | None = None,
        cached_at_from: str | None = None,
        cached_at_to: str | None = None,
        limit: int | None = None,
        sort: Literal["createdAt_desc", "createdAt_asc", "cachedAt_desc", "cachedAt_asc", "duration_desc", "duration_asc"] | None = None,
        linked_account_id: str | None = None,
        max_items: int | None = None,
    ) -> AsyncIterator[Any]:
        """Query Vault+ media: every item, fetching pages as needed.

        Yields the `items` entries of each page (async generator). Stops after `max_items` items when set.
        """
        return apaginate(
            lambda cursor: self.list(status=status, type=type, content_type=content_type, duration_min=duration_min, duration_max=duration_max, created_at_from=created_at_from, created_at_to=created_at_to, cached_at_from=cached_at_from, cached_at_to=cached_at_to, limit=limit, sort=sort, cursor=cursor, linked_account_id=linked_account_id),
            items="items",
            next_cursor=("nextCursor",),
            has_more=None,
            max_items=max_items,
        )


