class AsyncOFAuthClient(AsyncAPIClient):
    """OFAuth V3 API client for one authorization (async, httpx.AsyncClient).

    Operations return parsed JSON (dict / list / None) and raise `OFAuthAPIError`
    on error responses. Bodies may be dicts or Pydantic models from `onlyfans_sdk.models`.

    Example:
        async with AsyncOFAuthClient(access_token=tokens, linked_account_id="conn_123") as client:
            profile = await client.access.profile.get()
            async for chat in client.access.chats.iterate(max_items=50):
                print(chat["user"]["id"])
    """

    access: AsyncAccessNamespace
    """`access` operations."""
    authorization: AsyncAuthorizationNamespace
    """`authorization` operations."""
    link: AsyncLinkNamespace
    """`link` operations."""
    linked_accounts: AsyncLinkedAccountsNamespace
    """`linked_accounts` operations."""
    vault_plus: AsyncVaultPlusNamespace
    """`vault_plus` operations."""
    realtime: AsyncRealtimeNamespace
    """Realtime over Server-Sent Events: `client.realtime()` returns a `RealtimeConnection` (asyncio),
    and `await client.realtime.create_stream_url()` mints a stream URL for a browser.
    """

    def __init__(
        self,
        access_token: AccessTokenSource,
        *,
        linked_account_id: str | None = None,
        base_url: str = DEFAULT_API_URL,
        headers: Mapping[str, str] | None = None,
        timeout: float = DEFAULT_TIMEOUT,
        max_retries: int = DEFAULT_MAX_RETRIES,
        max_retry_delay: float = DEFAULT_MAX_RETRY_DELAY,
        on_request: RequestHook | None = None,
        on_response: ResponseHook | None = None,
        debug: bool | DebugLogger | None = None,
        http_client: httpx.AsyncClient | None = None,
    ) -> None:
        """Args:
            access_token: Bearer access token: a string, a callable `(force_refresh: bool) -> str`,
                or a token getter owned by the caller's auth system.
            linked_account_id: Default linked account for Access and Vault+ operations.
            base_url: API origin. Defaults to `https://api.ofauth.com`.
            headers: Extra headers sent with every request.
            timeout: Seconds per attempt (default 60). Upload part PUTs use at least 300.
            max_retries: Retries for network errors, 429, and 502/503/504 (default 2; 0 disables).
                Network errors and 502/503/504 are retried for GET, PUT, and DELETE only.
            max_retry_delay: Raise instead of retrying when the server asks to wait longer (default 60 s).
            on_request: Called with a `RequestInfo` before each attempt (authorization redacted).
            on_response: Called with a `ResponseInfo` after each attempt. Hook errors are ignored.
            debug: True, or a `(line: str) -> None` logger, to log one line per attempt. Defaults to
                the `OFAUTH_DEBUG=1` environment variable. Never logs tokens or bodies.
            http_client: Your own `httpx.AsyncClient` (you close it).
        """
        super().__init__(
            access_token,
            linked_account_id=linked_account_id,
            base_url=base_url,
            headers=headers,
            timeout=timeout,
            max_retries=max_retries,
            max_retry_delay=max_retry_delay,
            on_request=on_request,
            on_response=on_response,
            debug=debug,
            http_client=http_client,
        )
        self.access = AsyncAccessNamespace(self)
        self.authorization = AsyncAuthorizationNamespace(self)
        self.link = AsyncLinkNamespace(self)
        self.linked_accounts = AsyncLinkedAccountsNamespace(self)
        self.vault_plus = AsyncVaultPlusNamespace(self)
        self.realtime = AsyncRealtimeNamespace(self)

    def with_options(self, **options: Any) -> AsyncOFAuthClient:
        """A copy with some options changed. Shares the HTTP client and token source.

        Options: `linked_account_id`, `base_url`, `headers`, `timeout`, `max_retries`,
        `max_retry_delay`, `on_request`, `on_response`, `debug`.

        Example:
            await client.with_options(max_retries=0, timeout=10).access.profile.get()
        """
        return AsyncOFAuthClient(
            self._access_token,
            http_client=self._http,
            **self._options(options),
        )

    def with_linked_account(self, linked_account_id: str) -> AsyncOFAuthClient:
        """A client for another linked account of the same authorization. Shares the HTTP client."""
        return self.with_options(linked_account_id=linked_account_id)

    async def upload_media(
        self,
        data: UploadData,
        *,
        filename: str,
        content_type: str | None = None,
        linked_account_id: str | None = None,
        etag: str | None = None,
        vault_upload: Mapping[str, Any] | None = None,
        on_progress: ProgressCallback | None = None,
    ) -> UploadMediaResult:
        """Upload a file (start, PUT parts, finalize).

        Returns the upload id to use in `mediaItems`, or the existing media when the
        file is already in the vault. See `uploads.upload_media` for the arguments.

        Scope: `vault:write`
        """
        return await async_upload_media(
            self,
            data,
            filename=filename,
            content_type=content_type,
            linked_account_id=linked_account_id,
            etag=etag,
            vault_upload=vault_upload,
            on_progress=on_progress,
        )
